    "id": "usp-sp-2025-021",
    "number": 21,
    "stem": "Mulher, 32 anos de idade, natural e procedente de São Paulo, procura o serviço de emergência com queixa de adinamia há 7 dias e sangramento vaginal abundante há 2 dias. Nega comorbidades, tabagismo, etilismo, uso de medicamentos ou suplementos. Ao exame físico, apresenta FC de 100 bpm, PA de 100x50 mmHg, temperatura axilar de 38 °C; bom estado geral, descorada 2+/4+, anictérica, tem petéquias na mucosa jugal e nos membros inferiores; sem adenomegalias ou outros achados.\n\n• Exames laboratoriais:\nHb: 6,2 g/dL\nVCM: 84,7 fL | HCM: 29,7 pg | RDW: 18%\nReticulócitos: 23.000/mm3\nLeucócitos: 1.100/mm³ (Neutrófilos: 440/mm³, Linfócitos: 850/mm³, Monócitos: 40/mm³, Eosinófilos: 10/mm³)\nPlaquetas: 8.000/mm³\nHematoscopia com poiquilocitose e esferócitos.\n\nAssinale a alternativa que indica a mais provável hipótese diagnóstica e a correta condução clínica desta paciente.",
