    "stem": "Mulher, 52 anos de idade, apresentou lesão cutânea hipercrômica em antebraço direito. Foi realizada biópsia excisional da lesão, com o seguinte anatomopatológico:\n\n• Melanoma cutâneo invasivo;\n• Tipo histológico: extensivo superficial;\n• Nível IV de Clark;\n• Breslow: 4,1 mm;\n• Ulceração: presente;\n• Índice mitótico: 3/mm²;\n• Invasão perineural: presente;\n• Margens cirúrgicas radiais: comprometidas;\n• Margens cirúrgicas profundas: livres.\n\nQuais são os fatores de maior impacto prognóstico no anatomopatológico do caso apresentado?",
