    "id": "usp-sp-2025-066",
    "number": 66,
    "stem": "Mulher, 59 anos de idade, teve diagnóstico de adenocarcinoma de cólon direito há 1 mês e meio. Foi realizada tomografia de abdome que revelou quatro nódulos hepáticos nos segmentos 5, 6 e 7 de cerca de 2,5 cm cada um. A dosagem do CEA foi de 20 mg/dL. Enquanto aguardava encaminhamento para o centro de referência para o tratamento, evoluiu com quadro de obstrução intestinal. A paciente encontra-se estável no Serviço de Emergência. Qual é a melhor conduta neste momento?",
