    "id": "usp-sp-2025-107",
    "number": 107,
    "stem": "Bebê, 5 meses de idade, previamente hígido, comparece à consulta oftalmológica. A mãe relata que “os olhos da criança são grandes desde o nascimento” e que o olho esquerdo ficou “mais branco” há 2 dias. Refere ainda, que a criança lacrimeja em excesso e tem dificuldade para abrir os olhos em ambientes claros. Qual é a principal hipótese diagnóstica?",
